        <div style={{ position: 'absolute', top: '50%', left: '50%', transform: 'translate(-50%, -50%)', width: 400, height: 400, opacity: 0.04, borderRadius: '50%', overflow: 'hidden' }}>
          <img src={`data:image/jpeg;base64,${HOUSE_LOGO}`} alt="" style={{ width: '100%', height: '100%', objectFit: 'cover', filter: 'grayscale(100%) brightness(3)' }}/>
        </div>
